async function apiRequest(action,data={},method='POST') {
 const fd=data instanceof FormData?data:new FormData();
 if(!(data instanceof FormData))Object.entries(data).forEach(([k,v])=>fd.set(k,String(v??'')));
 fd.set('action',action);fd.set('_csrf',BOOT.csrf);
 let res;
 try{res=await fetch('api.php',{method,body:fd,credentials:'same-origin',headers:{'X-CSRF-Token':BOOT.csrf}});}catch(e){throw new Error('Sem conexão com o servidor. Verifique sua internet.');}
 const body=await res.json().catch(()=>({ok:false,error:'Resposta inválida do servidor.'}));
 if(res.status===401){window.location.href='acesso.php';throw Error('Sua sessão expirou.');}
 if(!res.ok||!body.ok)throw Error(body.error||'Operação não concluída.');
 return body;
}
async function apiGet(action,params={}) {
 const q=new URLSearchParams({action,...params});let res;
 try{res=await fetch('api.php?'+q.toString(),{credentials:'same-origin'});}catch(e){throw new Error('Sem conexão com o servidor.');}
 const body=await res.json().catch(()=>({ok:false,error:'Resposta inválida do servidor.'}));
 if(res.status===401){window.location.href='acesso.php';throw Error('Sua sessão expirou.');}
 if(!res.ok||!body.ok)throw Error(body.error||'Consulta não concluída.');
 return body;
}
async function reloadData(){const result=await apiGet('data.reload');db=result.records;return result;}
