function toast(msg, tone='success'){const el=$('#toast-root');if(!el)return;el.innerHTML=`<div class="toast ${tone}">${I(tone==='success'?'check':'info')}<span>${S(msg)}</span><button data-action="close-toast" aria-label="Fechar aviso">${I('x')}</button></div>`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.innerHTML='',3900);}
function heading(title,subtitle,eyebrow,actions=''){return `<div class="page-head"><div><div class="eyebrow"><span></span>${S(eyebrow)}</div><h1>${S(title)}</h1><p>${S(subtitle)}</p></div><div class="page-actions">${actions}</div></div>`;}
function btn(label,action,style='primary',other=''){return `<button class="btn ${style}" data-action="${action}" ${other}>${label}</button>`;}
const exportBtn=(key)=>btn(I('download')+' Exportar CSV','export','secondary',`data-module="${key}"`);
