function statCard(label,value,icon,variant='sea',foot=''){return `<div class="metric-card"><div class="metric-top"><span>${S(label)}</span><div class="metric-icon ${variant}">${I(icon)}</div></div><div class="metric-value">${value}</div><div class="metric-foot">${foot?`${I('arrowup')} ${S(foot)}`:'Dados registrados no sistema'}</div></div>`;}
function panel(title,subtitle,content,toolbar='',cls=''){return `<section class="panel ${cls}"><div class="panel-head"><div><h3>${title}</h3>${subtitle?`<p>${subtitle}</p>`:''}</div>${toolbar}</div>${content}</section>`;}
function notice(){return `<div class="demo-note">${I('shield')} <span><strong>Dados armazenados com segurança.</strong> As alterações são registradas no banco MySQL e identificadas na auditoria. Verifique se registros importados como exemplo não são confundidos com dados oficiais.</span></div>`;}
function statusCounts(key){const rows=allRecords(key), counts={};rows.forEach(r=>counts[r.status]=(counts[r.status]||0)+1);return counts;}
function tableValue(r,key){const v=r[key];if(key==='progresso')return `<div class="table-progress"><strong>${num(v)}%</strong>${progress(v)}</div>`;if(key==='status'||key==='condicao'||key==='prioridade')return pill(v);if(key==='valor'||key==='orcamento')return `<strong class="tabular">${BRL(v)}</strong>`;if(key==='quantidade')return `<strong class="tabular">${num(v)}</strong>`;if(key==='data'||key==='inicio'||key==='fim'||key==='prazo')return dateBR(v);if(key==='title')return `<strong class="row-primary">${S(v)}</strong>`;if(key==='id')return `<span class="code-tag">${S(v)}</span>`;return S(v ?? '—');}
function filtered(key){let items=[...allRecords(key)];const q=state.search.toLocaleLowerCase('pt-BR').trim();if(q)items=items.filter(r=>Object.values(r).some(v=>String(v).toLocaleLowerCase('pt-BR').includes(q)));if(state.status!=='all')items=items.filter(r=>r.status===state.status);if(state.sortKey)items.sort((a,b)=>{const x=a[state.sortKey],y=b[state.sortKey];return (typeof x==='number'&&typeof y==='number'?x-y:String(x??'').localeCompare(String(y??''),'pt-BR'))*state.sortDir;});return items;}
function table(key){const c=config[key],rows=filtered(key);return `<div class="table-wrap"><table class="data-table"><thead><tr>${c.columns.map(([k,t])=>`<th><button class="sort-button" data-action="sort" data-field="${k}">${S(t)} ${I(state.sortKey===k?(state.sortDir===1?'arrowup':'chevron'):'chevron')}</button></th>`).join('')}<th class="actions-col">AÇÕES</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${c.columns.map(([k])=>`<td>${tableValue(r,k)}</td>`).join('')}<td class="actions-col"><div class="row-buttons"><button class="row-icon" data-action="detail" data-module="${key}" data-id="${S(r.id)}" aria-label="Ver detalhes de ${S(r.title)}" title="Ver detalhes">${I('eye')}</button>${mayWrite?`<button class="row-icon" data-action="edit" data-module="${key}" data-id="${S(r.id)}" aria-label="Editar ${S(r.title)}" title="Editar">${I('edit')}</button>`:''}</div></td></tr>`).join(''):`<tr><td colspan="${c.columns.length+1}"><div class="empty-state">${I('search')}<strong>Nenhum registro encontrado</strong><span>Altere a busca ou os filtros para tentar novamente.</span><button class="text-link" data-action="clear-filters">Limpar filtros ${I('right')}</button></div></td></tr>`}</tbody></table></div><div class="table-footer"><span>Exibindo <strong>${rows.length}</strong> de <strong>${allRecords(key).length}</strong> registros</span><span>Atualizado no MySQL</span></div>`;}
function filterBar(key){const values=[...new Set(allRecords(key).map(r=>r.status).filter(Boolean))];return `<div class="filter-toolbar"><label class="table-search">${I('search')}<input id="table-search" type="search" value="${S(state.search)}" placeholder="Buscar por nome, código ou setor..." aria-label="Buscar registros do módulo"></label><div class="filter-right"><label class="select-wrap">${I('filter')}<select id="status-filter" aria-label="Filtrar por situação"><option value="all">Todas as situações</option>${values.map(s=>`<option value="${S(s)}" ${state.status===s?'selected':''}>${S(s)}</option>`).join('')}</select>${I('chevron')}</label>${exportBtn(key)}</div></div>`;}
function tablePanel(key,headingTitle='Registros cadastrados',sub='Consulte, filtre e gerencie os registros do módulo.'){return `<section class="panel list-panel"><div class="panel-head"><div><h3>${headingTitle}</h3><p>${sub}</p></div><span class="panel-count">${allRecords(key).length} registros</span></div>${filterBar(key)}<div id="module-table">${table(key)}</div></section>`;}
